"""Simple protocol conformance tests for caching classes."""

from unittest.mock import AsyncMock

import pytest

from mcp_tracker.tracker.caching.client import make_cached_protocols
from mcp_tracker.tracker.proto.fields import GlobalDataProtocol
from mcp_tracker.tracker.proto.issues import IssueProtocol
from mcp_tracker.tracker.proto.queues import QueuesProtocol
from mcp_tracker.tracker.proto.users import UsersProtocol


class TestCachingProtocolConformance:
    @pytest.fixture
    def cache_config(self) -> dict[str, int]:
        return {"ttl": 300}

    @pytest.fixture
    def mock_original(self) -> AsyncMock:
        return AsyncMock()

    def test_caching_queues_implements_protocol(
        self, cache_config: dict[str, int], mock_original: QueuesProtocol
    ) -> None:
        cache_collection = make_cached_protocols(cache_config)
        instance = cache_collection.queues(mock_original)

        assert isinstance(instance, QueuesProtocol)

    def test_caching_issues_implements_protocol(
        self, cache_config: dict[str, int], mock_original: IssueProtocol
    ) -> None:
        cache_collection = make_cached_protocols(cache_config)
        instance = cache_collection.issues(mock_original)

        assert isinstance(instance, IssueProtocol)

    def test_caching_global_data_implements_protocol(
        self, cache_config: dict[str, int], mock_original: GlobalDataProtocol
    ) -> None:
        cache_collection = make_cached_protocols(cache_config)
        instance = cache_collection.global_data(mock_original)

        assert isinstance(instance, GlobalDataProtocol)

    def test_caching_users_implements_protocol(
        self, cache_config: dict[str, int], mock_original: UsersProtocol
    ) -> None:
        cache_collection = make_cached_protocols(cache_config)
        instance = cache_collection.users(mock_original)

        assert isinstance(instance, UsersProtocol)

from collections.abc import AsyncIterator
from contextlib import asynccontextmanager, suppress
from typing import Any
from unittest.mock import AsyncMock

import pytest
import pytest_asyncio
from mcp.client.session import ClientSession, ElicitationFnT
from mcp.server import FastMCP
from mcp.shared.memory import create_connected_server_and_client_session
from mcp.types import CallToolResult

from mcp_tracker.mcp.context import AppContext
from mcp_tracker.mcp.server import Lifespan, create_mcp_server
from mcp_tracker.settings import Settings
from mcp_tracker.tracker.proto.fields import GlobalDataProtocol
from mcp_tracker.tracker.proto.issues import IssueProtocol
from mcp_tracker.tracker.proto.queues import QueuesProtocol
from mcp_tracker.tracker.proto.users import UsersProtocol


@asynccontextmanager
async def safe_client_session(
    mcp_server: FastMCP[Any],
    elicitation_callback: ElicitationFnT | None = None,
) -> AsyncIterator[ClientSession]:
    """Context manager wrapper that handles anyio teardown issues.

    The MCP SDK's create_connected_server_and_client_session uses anyio
    task groups that can fail during cleanup in pytest-asyncio environments.
    This wrapper suppresses those cleanup errors since the test has already
    completed successfully at that point.
    """
    ctx_mgr = create_connected_server_and_client_session(
        mcp_server, raise_exceptions=True, elicitation_callback=elicitation_callback
    )
    session = await ctx_mgr.__aenter__()
    try:
        yield session
    finally:
        with suppress(RuntimeError, ExceptionGroup):
            await ctx_mgr.__aexit__(None, None, None)


def get_tool_result_content(result: CallToolResult) -> Any:
    """Extract content from a tool result using structuredContent.

    FastMCP populates structuredContent with the tool's return value:
    - Single Pydantic model: structuredContent is the model dict directly
    - Primitives (str, int) and lists: structuredContent = {'result': value}

    Args:
        result: The CallToolResult from client_session.call_tool()

    Returns:
        The tool's return value (dict, list, str, int, etc.)
    """
    structured = result.structuredContent
    assert structured is not None, "Tool result has no structuredContent"

    # If structuredContent has a 'result' key, return that (primitives, lists)
    # Otherwise return the whole dict (single Pydantic model)
    if isinstance(structured, dict) and "result" in structured:
        return structured["result"]
    return structured


